		in flowCmd : Real;
		out outletIonDensity : Real;
		out outletParticleCount : Real;
		out outletOzonePpm : Real;
		out outletTemperature : ThermodynamicTemperatureValue;
		out outletFlowRate : Real;
		first start;
		then done;
	}
	action def AdjustControls {
		in measuredIon : Real;
		in targetIon : Real;
		in tolerance : Real;
