			in inletParticleCount = sense.particleCount;
			in inletOzonePpm = sense.ozonePpm;
			in inletTemperature = sense.temperature;
			in inletFlowRate = sense.flowRate;
			in chamberLoss = chamberLoss;
			in ionYield = ionYield;
			in intensityCmd = intensityCmd;
		}
		then action move : MoveAir {
			in inletIonDensity = inject.outletIonDensity;
			in inletParticleCount = inject.outletParticleCount;
			in inletOzonePpm = inject.outletOzonePpm;
			in inletTemperature = inject.outletTemperature;
			in flowCmd = flowCmd;
		}
		then action adjust : AdjustControls {
			in measuredIon = move.outletIonDensity;
			in targetIon = targetIon;
			in tolerance = ionTolerance;
